select.if:
select cdate,null portfolioId,null portfolioName,finprodType2,null type5,null finprodMarketId,null finprodAbbr, sum(marketValue) marketValue, CASE WHEN finprodType2 IN ('F08', 'F09', 'F16') THEN NULL ELSE sum(dscCostAmt) END dscCostAmt, sum(shareAmt) shareAmt, sum(tdyIntincexp) tdyIntincexp, round(sum(tdyAmtRation),2) tdyAmtRation, round(sum(ystAmtRation),2) ystAmtRation, round(sum(monthAmtRation),2) monthAmtRation, round(sum(yearAmtRation),2) yearAmtRation, '02' hasChildren, CONCAT(CONCAT(IFNULL( portfolioId,''),'_'),IFNULL(finprodType2,'null')) childInfo, CONCAT(IFNULL(portfolioId,'null'),'') parentInfo, finprodType2 as otherFinprodType2, portfolioName otherPortfolioName from
CONCAT(IFNULL(portfolioId,'null'),'') = #{parentId}
group by cdate,portfolioId,portfolioName,finprodType2 union all select cdate,null portfolioId,null portfolioName,null finprodType2, type5, case when finprodType2 IN ('F14', 'F15') THEN NULL ELSE finprodMarketId END finprodMarketId, finprodAbbr, sum(marketValue) marketValue, sum(dscCostAmt) dscCostAmt, sum(shareAmt) shareAmt, sum(tdyIntincexp) tdyIntincexp, round(sum(tdyAmtRation),2) tdyAmtRation, round(sum(ystAmtRation),2) ystAmtRation, round(sum(monthAmtRation),2) monthAmtRation, round(sum(yearAmtRation),2) yearAmtRation, '01' hasChildren, CONCAT(CONCAT(IFNULL(portfolioId,'null'),'_'),CONCAT(CONCAT(IFNULL(finprodType2,'null'),'_'),type5)) childInfo, CONCAT(CONCAT(IFNULL(portfolioId ,''),'_'),IFNULL(finprodType2,'null')) parentInfo, finprodType2 as otherFinprodType2, portfolioName otherPortfolioName from
CONCAT(CONCAT(portfolioId,'_'),IFNULL(finprodType2,'null')) = #{parentId}
group by cdate,portfolioId,portfolioName,finprodType2,type5,finprodMarketId,finprodAbbr

mapper.select:
select AA.finprodType2, sum(AA.marketValue) as marketValue, CASE WHEN AA.finprodType2 IN ('F08', 'F09', 'F16') THEN NULL ELSE sum(AA.dscCostAmt) END as dscCostAmt, round(sum(AA.amtRation),2) as amtRation, sum(IFNULL(AA.tdyIntincexp, 0)) as tdyIntincexp from (select A.finprodType2,A.marketValue,A.dscCostAmt,A.tdyIntincexp, (IFNULL(A.marketValue,0)+IFNULL(A.tdyIntincexp,0))*100/B.typeMarketValue as amtRation from ( select psv.CDATE as cdate,fpt.TYPE_8 as finprodType2, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT else psv.DSC_COST_AMT end as dscCostAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*psv.TDY_INTINCEXP when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.TDY_INTINCEXP when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*psv.TDY_INTINCEXP else psv.TDY_INTINCEXP end as tdyIntincexp, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) else (IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) end as marketValue from PTL_SEC_VALUTION psv
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null where 1=1
AND psv.PORTFOLIO_ID IN
#{item}
and DATE_FORMAT(psv.CDATE,'%Y-%m-%d') = #{searchDate}
AND fpt.TYPE_8 IN
#{item}
)A left join ( select psv.CDATE as cdate, sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)+IFNULL(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)+IFNULL(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)+IFNULL(psv.TDY_INTINCEXP,0)) else (IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)+IFNULL(psv.TDY_INTINCEXP,0)) end ) as typeMarketValue from PTL_SEC_VALUTION psv
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null where 1=1
AND psv.PORTFOLIO_ID IN
#{item}
and DATE_FORMAT(psv.CDATE,'%Y-%m-%d')= #{searchDate}
AND fpt.TYPE_8 IN
#{item}
group by psv.CDATE )B on A.cdate=B.cdate and B.typeMarketValue!=0) AA group by AA.finprodType2 union all SELECT assetHold.finprodType2, sum(assetHold.marketValue) as marketValue, sum(assetHold.dscCostAmt) as dscCostAmt, NULL amtRation, NULL tdyIntincexp from
where assetHold.finprodType2 = #{cash} group by assetHold.finprodType2

select A.finprodType2,A.marketValue,A.dscCostAmt,A.tdyIntincexp,
round((IFNULL(A.marketValue,0)+IFNULL(A.tdyIntincexp,0))*100/B.typeMarketValue,2) as amtRation
from (
select psv.CDATE as cdate,fpt.TYPE_8 as finprodType2,
sum(IFNULL(psv.MARKET_VALUE,0)) as marketValue,
sum(IFNULL(psv.DSC_COST_AMT,0)) as dscCostAmt,
sum(IFNULL(psv.TDY_INTINCEXP,0)) as tdyIntincexp
from PTL_SEC_PIERCE_VALUTION psv

inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null
where 1=1

    AND psv.PORTFOLIO_ID IN

        #{item}



    and DATE_FORMAT(psv.CDATE,'%Y-%m-%d') = #{searchDate}


    AND fpt.TYPE_8 IN

        #{item}


group by  psv.CDATE,fpt.TYPE_8
)A
left join (
select psv.CDATE as cdate,
sum(IFNULL(psv.MARKET_VALUE,0)+IFNULL(psv.TDY_INTINCEXP,0)) as typeMarketValue
from PTL_SEC_PIERCE_VALUTION psv

inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null
where 1=1

    AND psv.PORTFOLIO_ID IN

        #{item}



    and DATE_FORMAT(psv.CDATE,'%Y-%m-%d')= #{searchDate}


    AND fpt.TYPE_8 IN

        #{item}


group by psv.CDATE
)B on A.cdate=B.cdate and B.typeMarketValue!=0

        select portfolioId,
        pinanAssetType,
        customAssetTypeTwo,
        customAssetTypeThree,
        customAssetTypeFour,
        customAssetTypeFive
        from (select atd.portfolio_id as portfolioId,
        atd.pinan_asset_type as pinanAssetType,
        atd.custom_asset_type_two as customAssetTypeTwo,
        atd.custom_asset_type_three as customAssetTypeThree,
        atd.custom_asset_type_four as customAssetTypeFour,
        atd.custom_asset_type_five as customAssetTypeFive,
		row_number
		from (
			SELECT result.* FROM (
				SELECT tmp.*,
				@rownum := @rownum + 1 row,
				IF(
                        (

							@portfolio_id = tmp.portfolio_id and

								@pinan_asset_type = tmp.pinan_asset_type


								@custom_asset_type_two = tmp.custom_asset_type_two


								@custom_asset_type_three = tmp.custom_asset_type_three


								@custom_asset_type_four = tmp.custom_asset_type_four


								@custom_asset_type_five = tmp.custom_asset_type_five




								@pinan_asset_type = tmp.pinan_asset_type


								@custom_asset_type_two = tmp.custom_asset_type_two


								@custom_asset_type_three = tmp.custom_asset_type_three


								@custom_asset_type_four = tmp.custom_asset_type_four


								@custom_asset_type_five = tmp.custom_asset_type_five


                            ),
                        @rank := @rank + 1,
                        @rank := 1
                    ) AS row_number,

							@portfolio_id = tmp.portfolio_id and

								@pinan_asset_type = tmp.pinan_asset_type


								@custom_asset_type_two = tmp.custom_asset_type_two


								@custom_asset_type_three = tmp.custom_asset_type_three


								@custom_asset_type_four = tmp.custom_asset_type_four


								@custom_asset_type_five = tmp.custom_asset_type_five




								@pinan_asset_type = tmp.pinan_asset_type


								@custom_asset_type_two = tmp.custom_asset_type_two


								@custom_asset_type_three = tmp.custom_asset_type_three


								@custom_asset_type_four = tmp.custom_asset_type_four


								@custom_asset_type_five = tmp.custom_asset_type_five


				FROM (
                  SELECT atd.*
                  FROM ASSET_TARGET_DB atd WHERE 1 = 1 and DATE_FORMAT(atd.CDATE,'%Y-%m-%d') = #{searchDate}

						and atd.IS_PERNE= #{pass}


						and atd.portfolio_id= #{portfolioId}



						and atd.pinan_asset_type= #{type}

					and atd.pinan_asset_type is not NULL
                  ORDER BY CAST(atd.cdate as date) DESC
              ) tmp,
			  (SELECT @rownum := 0,

							@portfolio_id := null,

								@pinan_asset_type = null,


								@custom_asset_type_two = null,


								@custom_asset_type_three = null,


								@custom_asset_type_four = null,


								@custom_asset_type_five = null,




								@pinan_asset_type = null,


								@custom_asset_type_two = null,


								@custom_asset_type_three = null,


								@custom_asset_type_four = null,


								@custom_asset_type_five = null,


                      @rank := 0) a
			) result
		) atd where atd.row_number=1
        ) t

select.if:
SELECT portfolioId, hasChildren, childInfo, parentInfo, pinanAssetType, customAssetTypeTwo, customAssetTypeThree, customAssetTypeFour, customAssetTypeFive FROM ( SELECT @rownum:=@rownum+1 rownum, atd.portfolio_id AS portfolioId, atd.finprod_id AS finprodId, atd.branch, atd.is_perne AS isPerne, atd.cdate, atd.finprod_market_id AS finprodMarketId, atd.finprod_name AS finprodName, atd.pinan_asset_type AS pinanAssetType, atd.custom_asset_type_two AS customAssetTypeTwo, atd.custom_asset_type_three AS customAssetTypeThree, atd.custom_asset_type_four AS customAssetTypeFour, atd.custom_asset_type_five AS customAssetTypeFive, atd.faire_price AS fairePrice, atd.pos_amount AS posAmount, atd.prin, atd.pos_cost AS posCost, atd.pos_value AS posValue, atd.tdy_intincexp AS tdyIntincexp, atd.issue_party AS issueParty, atd.is_soe AS isSoe, atd.is_listed_company AS isListedCompany, atd.company_nature AS companyNature, atd.industry, atd.industry2, atd.vdate, atd.mdate, atd.term_days AS termDays, atd.counter_id AS counterId, atd.last_period AS lastPeriod, atd.latest_deal_date AS latestDealDate, atd.bshare_face_value AS bshareFaceValue, atd.issue_face_value AS issueFaceValue, atd.rate, atd.cost_rate AS costRate, atd.bpyield, atd.m_convexity mConvexity, atd.ex_info AS exInfo, atd.ex_next_date AS exNextDate, atd.last_ex_period AS lastExPeriod, atd.m_grade_result mGradeResult, atd.m_grade_org mGradeOrg, atd.b_grade_result bGradeResult, atd.b_grade_org bGradeOrg, atd.m_grade_result_in mGradeResultIn, atd.b_grade_result_in bGradeResultIn, atd.is_city_bond isCityBond, atd.city_bond_lev cityBondLev, atd.c_shares cShares, atd.s_shares sShares, atd.trade_market tradeMarket, atd.is_sus isSus, atd.is_right isRight, atd.ex_date exDate, atd.m_grade_org_in mGradeOrgIn, atd.b_grade_org_in bGradeOrgIn, atd.bshare_scale bshareScale, atd.profit_type profitType, atd.M_DURATION mDuration, atd.MDURATION mdurationAmend, '02' hasChildren,
CONCAT( CONCAT( IFNULL(atd.portfolio_id, 'null'),IFNULL(atd.pinan_asset_type, 'null')),'') childInfo, IF( @portfolio_id = atd.portfolio_id, @rank := @rank + 1, @rank := 1 ) AS row_number, @portfolio_id := atd.portfolio_id,
'root' parentInfo from ( SELECT * FROM ASSET_TARGET_DB ORDER BY portfolio_id, cdate ) atd, ( SELECT @rownum := 0, @CASH_ID := NULL, @rank := 0 )b WHERE 1=1
AND atd.PORTFOLIO_ID IN
#{item}
and DATE_FORMAT(atd.CDATE,'%Y-%m-%d') = #{searchDate}
AND atd.PROFIT_TYPE IN
#{item}
and atd.portfolio_id in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where user_id in
#{item}
)
AND atd.FINPROD_MARKET_ID IN
#{item}
and atd.IS_PERNE= #{pass} and atd.pinan_asset_type is not NULL
) t where t.row_number=1

select atd.portfolio_id as portfolioId,atd.finprod_id as finprodId,atd.branch,atd.is_perne as isPerne,atd.cdate ,atd.finprod_market_id as finprodMarketId,atd.finprod_name as finprodName,atd.pinan_asset_type as pinanAssetType,atd.custom_asset_type_two as customAssetTypeTwo,atd.custom_asset_type_three as customAssetTypeThree,atd.custom_asset_type_four as customAssetTypeFour,atd.custom_asset_type_five as customAssetTypeFive,atd.faire_price as fairePrice,sum(atd.pos_amount) as posAmount,atd.prin,sum(atd.pos_cost) as posCost,sum(atd.pos_value) as posValue,sum(atd.tdy_intincexp) as tdyIntincexp,atd.issue_party as issueParty,atd.is_soe as isSoe,atd.is_listed_company as isListedCompany,atd.company_nature as companyNature,atd.industry ,atd.industry2 , atd.vdate ,atd.mdate,atd.term_days as termDays,atd.counter_id as counterId,atd.last_period as lastPeriod,atd.latest_deal_date as latestDealDate,atd.bshare_face_value as bshareFaceValue,atd.issue_face_value as issueFaceValue,atd.rate,atd.cost_rate as costRate,atd.bpyield ,atd.m_convexity mConvexity,atd.ex_info as exInfo,atd.ex_next_date as exNextDate,atd.last_ex_period as lastExPeriod,atd.m_grade_result mGradeResult,atd.m_grade_org mGradeOrg,atd.b_grade_result bGradeResult,atd.b_grade_org bGradeOrg,atd.m_grade_result_in mGradeResultIn,atd.b_grade_result_in bGradeResultIn,atd.is_city_bond isCityBond,atd.city_bond_lev cityBondLev,atd.c_shares cShares,atd.s_shares sShares, atd.trade_market tradeMarket,atd.is_sus isSus,atd.is_right isRight,atd.ex_date exDate,atd.m_grade_org_in mGradeOrgIn,atd.b_grade_org_in bGradeOrgIn,atd.bshare_scale bshareScale,atd.profit_type profitType,atd.M_DURATION mDuration,atd.MDURATION mdurationAmend , '01' hasChildren,atd.dv01 dv01,atd.float_ingpl_add_price floatIngplAddPrice,atd.float_ingpl_add floatIngplAdd,
CONCAT( CONCAT( IFNULL(atd.portfolio_id, 'null'),IFNULL(atd.pinan_asset_type, 'null')),'') parentInfo, CONCAT(CONCAT(CONCAT(CONCAT(IFNULL(atd.PORTFOLIO_ID, 'null'), IFNULL(atd.pinan_asset_type, 'null')), IFNULL(atd.custom_asset_type_two, 'null')), IFNULL(atd.finprod_id, 'null')),'') childInfo
CONCAT( CONCAT( CONCAT( IFNULL(atd.portfolio_id, 'null'),IFNULL(atd.pinan_asset_type, 'null')),IFNULL(atd.custom_asset_type_two, 'null')),'') parentInfo, CONCAT(CONCAT(CONCAT(CONCAT(CONCAT(IFNULL(atd.PORTFOLIO_ID, 'null'),IFNULL(atd.finprod_id,'null')), IFNULL(atd.pinan_asset_type,'null')),IFNULL(custom_asset_type_two,'null')),IFNULL(custom_asset_type_three,'null')),'') childInfo
CONCAT( CONCAT( CONCAT( CONCAT( IFNULL(atd.portfolio_id, 'null'), IFNULL(atd.pinan_asset_type, 'null')),IFNULL(atd.custom_asset_type_two, 'null')),IFNULL(atd.custom_asset_type_three, 'null')),'') parentInfo, CONCAT(CONCAT(CONCAT(CONCAT(CONCAT(CONCAT(IFNULL(atd.PORTFOLIO_ID, 'null'),IFNULL(atd.finprod_id,'null')), IFNULL(atd.pinan_asset_type,'null')),IFNULL(custom_asset_type_two,'null')),IFNULL(custom_asset_type_three,'null')),IFNULL(custom_asset_type_four,'null')),'') childInfo
CONCAT( CONCAT( CONCAT( CONCAT( CONCAT( IFNULL(atd.portfolio_id, 'null'),IFNULL(atd.pinan_asset_type, 'null')),IFNULL(atd.custom_asset_type_two, 'null')),IFNULL(atd.custom_asset_type_three, 'null')),IFNULL(atd.custom_asset_type_four, 'null')),'') parentInfo, CONCAT( CONCAT(CONCAT(CONCAT(CONCAT(CONCAT(CONCAT(IFNULL(atd.PORTFOLIO_ID, 'null'),IFNULL(atd.finprod_id,'null')), IFNULL(atd.pinan_asset_type,'null')),IFNULL(custom_asset_type_two,'null')),IFNULL(custom_asset_type_three,'null')),IFNULL(custom_asset_type_four,'null')),IFNULL(custom_asset_type_five,'null')),'') childInfo
CONCAT( CONCAT( CONCAT( CONCAT( CONCAT( CONCAT( IFNULL(atd.portfolio_id, 'null'),IFNULL(atd.pinan_asset_type, 'null')),IFNULL(atd.custom_asset_type_two, 'null')),IFNULL(atd.custom_asset_type_three, 'null')),IFNULL(atd.custom_asset_type_four, 'null')),IFNULL(atd.custom_asset_type_five, 'null')),'') parentInfo, CONCAT( CONCAT( CONCAT(CONCAT(CONCAT(CONCAT(CONCAT(CONCAT(IFNULL(atd.PORTFOLIO_ID, 'null'),IFNULL(atd.finprod_id,'null')), IFNULL(atd.pinan_asset_type,'null')),IFNULL(custom_asset_type_two,'null')),IFNULL(custom_asset_type_three,'null')),IFNULL(custom_asset_type_four,'null')),IFNULL(custom_asset_type_five,'null')),IFNULL(FINPROD_ID,'null')),'') childInfo
