and CONCAT( CONCAT( CONCAT( CONCAT( CONCAT( IFNULL(atd.portfolio_id, 'null'),IFNULL(atd.pinan_asset_type, 'null')),IFNULL(atd.custom_asset_type_two, 'null')),IFNULL(atd.custom_asset_type_three, 'null')),IFNULL(atd.custom_asset_type_four, 'null')),'')= #{parentId}
and CONCAT( CONCAT( CONCAT( CONCAT( CONCAT( CONCAT( IFNULL(atd.portfolio_id, 'null'),IFNULL(atd.pinan_asset_type, 'null')),IFNULL(atd.custom_asset_type_two, 'null')),IFNULL(atd.custom_asset_type_three, 'null')),IFNULL(atd.custom_asset_type_four, 'null')),IFNULL(atd.custom_asset_type_five, 'null')),'')= #{parentId}
