mapper.sql:
( select A.cdate,A.portfolioId,A.portfolioName,A.finprodType2,A.type5,A.finprodMarketId,A.finprodAbbr,A.marketValue, CASE WHEN A.finprodType2 IN ('F08', 'F09', 'F16') THEN NULL ELSE A.dscCostAmt END dscCostAmt, A.shareAmt, A.tdyIntincexp, ((IFNULL(A.marketValue, 0) + IFNULL(A.tdyIntincexp, 0)) / B.typeMarketValue) * 100 as tdyAmtRation, CASE WHEN DATE_FORMAT( A.CDATE, '%Y-%m-%d' ) = DATE_FORMAT( A.VDATE, '%Y-%m-%d') THEN null ELSE (((IFNULL(A.marketValue, 0) + IFNULL(A.tdyIntincexp, 0)) / B.typeMarketValue) - IFNULL(C.ystAmtRation, 0)) * 100 END ystAmtRation, CASE WHEN DATE_FORMAT( A.CDATE, '%Y-%m-%d' ) = DATE_FORMAT( A.VDATE, '%Y-%m-%d') THEN null ELSE (((IFNULL(A.marketValue, 0) + IFNULL(A.tdyIntincexp, 0)) / B.typeMarketValue) - IFNULL(D.monthAmtRation, 0)) * 100 END monthAmtRation, CASE WHEN DATE_FORMAT( A.CDATE, '%Y-%m-%d' ) = DATE_FORMAT( A.VDATE, '%Y-%m-%d') THEN null ELSE (((IFNULL(A.marketValue, 0) + IFNULL(A.tdyIntincexp, 0)) / B.typeMarketValue) - IFNULL(F.yearAmtRation, 0)) * 100 END yearAmtRation from ( select pp.VDATE AS vdate,psv.CDATE as cdate,psv.PORTFOLIO_ID as portfolioId,pp.PORTFOLIO_NAME as portfolioName, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT else psv.DSC_COST_AMT end as dscCostAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*psv.TDY_INTINCEXP when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.TDY_INTINCEXP when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*psv.TDY_INTINCEXP else psv.TDY_INTINCEXP end as tdyIntincexp, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) else (IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) end as marketValue, psv.SHARE_AMT as shareAmt, fpt.TYPE_8 as finprodType2, IFNULL(fp.FINPROD_MARKET_ID,psv.FINPROD_ID) as finprodMarketId, IFNULL(fp.FINPROD_ID,psv.FINPROD_ID) AS finprodId, IFNULL(fp.FINPROD_ABBR, fp.FINPROD_NAME) as finprodAbbr, CASE WHEN fpt.TYPE_8='F07' THEN fpt.TYPE_7 WHEN fpt.TYPE_8='F10' THEN fpt.TYPE_7 ELSE fpt.TYPE_6 END as type5 from PTL_SEC_VALUTION psv left join FIN_PRODUCT fp on psv.FINPROD_ID=fp.FINPROD_ID left join PTL_PORTFOLIO pp on psv.PORTFOLIO_ID=pp.PORTFOLIO_ID left join FIN_PRODUCT_ADD fpa ON IFNULL(pp.PARENT_PORTFOLIO_ID,pp.PORTFOLIO_ID) = fpa.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT FP1 ON FPA.FINPROD_ID = FP1.FINPROD_ID inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null where FP1.FINPROD_TYPE2 = 'F16'
AND psv.PORTFOLIO_ID IN
#{item}
and DATE_FORMAT(psv.CDATE,'%Y-%m-%d') = #{searchDate}
AND fpt.TYPE_8 IN
#{item}
AND fpa.PROD_MANAGER IN
#{item}
AND (psv.DSC_COST_AMT>0 or psv.SHARE_AMT>0) ) A left join( select psv.CDATE as cdate,psv.PORTFOLIO_ID as portfolioId, sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)+IFNULL(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)+IFNULL(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)+IFNULL(psv.TDY_INTINCEXP,0)) else (IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)+IFNULL(psv.TDY_INTINCEXP,0)) end ) as typeMarketValue from PTL_SEC_VALUTION psv
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null where 1=1
AND psv.PORTFOLIO_ID IN
#{item}
and DATE_FORMAT(psv.CDATE,'%Y-%m-%d')= #{searchDate}
group by psv.CDATE,psv.PORTFOLIO_ID ) B on A.portfolioId=B.portfolioId and A.cdate=B.cdate and B.typeMarketValue!=0 left join( select AA.cdate,AA.portfolioId,AA.finprodType2,AA.finprodId,round((IFNULL(AA.marketValue, 0) + IFNULL(AA.tdyIntincexp, 0)) / BB.typeMarketValue, 4) as ystAmtRation from( select psv.CDATE as cdate, psv.PORTFOLIO_ID as portfolioId, psv.FINPROD_ID AS finprodId, sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) else (IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) end ) as marketValue, sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(IFNULL(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_INTINCEXP,0)) else (IFNULL(psv.TDY_INTINCEXP,0)) end ) as tdyIntincexp, fpt.TYPE_8 as finprodType2 from PTL_SEC_VALUTION psv
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null inner join ( select PORTFOLIO_ID portfolioId,max(CDATE) as maxCdate from PTL_SEC_VALUTION where 1=1
AND PORTFOLIO_ID IN
#{item}
and DATE_FORMAT(CDATE,'%Y-%m-%d') < #{searchDate}
group by PORTFOLIO_ID )E on E.portfolioId=psv.PORTFOLIO_ID where psv.CDATE=E.maxCdate
