sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)+IFNULL(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)+IFNULL(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)+IFNULL(psv.TDY_INTINCEXP,0)) else (IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)+IFNULL(psv.TDY_INTINCEXP,0)) end ) as typeMarketValue from PTL_SEC_VALUTION psv
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null inner join ( select PORTFOLIO_ID portfolioId,max(CDATE) as maxCdate from PTL_SEC_VALUTION where 1=1
AND PORTFOLIO_ID IN
#{item}
and DATE_FORMAT(CDATE,'%Y-%m-%d') < #{searchDate}
group by PORTFOLIO_ID )E on E.portfolioId=psv.PORTFOLIO_ID where psv.CDATE=E.maxCdate
AND psv.PORTFOLIO_ID IN
